-- Migration: tabel konten situs (teks statis + daftar item) untuk panel admin.
-- Sumber data: src/lib/konten-defs.json (dibuat otomatis oleh gen-migration-konten.mjs).
--
-- `konten`      : satu baris = satu key teks (hero, judul section, footer, dst).
-- `konten_item` : baris daftar (pengajar, profil lulusan, kontak, materi, fitur program).

CREATE TABLE `konten` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `kunci` VARCHAR(191) NOT NULL,
  `label` VARCHAR(191) NOT NULL,
  `tipe` VARCHAR(20) NOT NULL DEFAULT 'teks',
  `grup` VARCHAR(50) NOT NULL,
  `nilai` LONGTEXT NOT NULL,
  `urutan` INT NOT NULL DEFAULT 0,
  `tampil` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_by_id` INT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `konten_kunci_key` (`kunci`),
  KEY `konten_grup_urutan_idx` (`grup`, `urutan`),
  CONSTRAINT `konten_updated_by_id_fkey` FOREIGN KEY (`updated_by_id`)
    REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `konten_item` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `grup` VARCHAR(50) NOT NULL,
  `judul` VARCHAR(191) NOT NULL,
  `deskripsi` TEXT NULL,
  `url` VARCHAR(500) NULL,
  `ikon` VARCHAR(50) NULL,
  `file_url` VARCHAR(500) NULL,
  `file_name` VARCHAR(255) NULL,
  `urutan` INT NOT NULL DEFAULT 0,
  `tampil` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_by_id` INT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `konten_item_grup_urutan_idx` (`grup`, `urutan`),
  CONSTRAINT `konten_item_updated_by_id_fkey` FOREIGN KEY (`updated_by_id`)
    REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

